SELECT e.id AS educationId, COALESCE(ep.progress_rate, 0) AS progressRate, COALESCE(ep.status, 'NOT_STARTED') AS status, ep.completed_at AS completedAt, COUNT(sc.id) AS completedStages FROM educations e LEFT JOIN education_progress ep ON ep.education_id = e.id AND ep.user_id = #{userId} LEFT JOIN education_stages es ON es.education_id = e.id LEFT JOIN stage_completions sc ON sc.stage_id = es.id AND sc.user_id = #{userId} WHERE e.id IN
#{id}
GROUP BY e.id, ep.progress_rate, ep.status, ep.completed_at

SELECT u.id AS userId, u.name AS userName, d.name AS departmentName, e.title AS educationTitle, ep.progress_rate AS progressRate, e.completion_criteria AS completionCriteria FROM education_progress ep JOIN users u ON u.id = ep.user_id LEFT JOIN departments d ON d.id = u.department_id JOIN educations e ON e.id = ep.education_id WHERE ep.status != 'COMPLETED'
AND ep.education_id = #{educationId}
ORDER BY ep.id ASC LIMIT #{size} OFFSET #{offset}
